using FluNET.Execution.Planning;using FluNET.Execution.Workflow;using System.Collections.Concurrent;namespace FluNET.Automation;public sealed record AutomationScheduleState(string AutomationId,DateTimeOffset?NextDue);public interface IAutomationScheduleStore{ValueTask<AutomationScheduleState?>GetAsync(string automationId,CancellationToken cancellationToken=default);ValueTask SetAsync(AutomationScheduleState state,CancellationToken cancellationToken=default);}public sealed class InMemoryAutomationScheduleStore:IAutomationScheduleStore{private readonly ConcurrentDictionary<string,AutomationScheduleState>s=new(StringComparer.OrdinalIgnoreCase);public ValueTask<AutomationScheduleState?>GetAsync(string id,CancellationToken ct=default){ct.ThrowIfCancellationRequested();s.TryGetValue(id,out AutomationScheduleState?state);return ValueTask.FromResult(state);}public ValueTask SetAsync(AutomationScheduleState state,CancellationToken ct=default){ct.ThrowIfCancellationRequested();s[state.AutomationId]=state;return ValueTask.CompletedTask;}}public sealed record AutomationRunResult(AutomationDefinition Automation,IReadOnlyList<ExecutionStepResult>Steps,object?Result,Exception?Error){public bool IsSuccess=>Error is null;}public sealed class AutomationScheduler(ExecutionPlanExecutor executor,IAutomationScheduleStore store){private readonly ConcurrentDictionary<string,AutomationDefinition>a=new(StringComparer.OrdinalIgnoreCase);private readonly SemaphoreSlim gate=new(1,1);public async ValueTask RegisterAsync(AutomationDefinition definition,DateTimeOffset now,CancellationToken ct=default){if(!definition.Template.IsValid)throw new InvalidOperationException($"Automation '{definition.Id}' does not have a valid workflow template.");a[definition.Id]=definition;if(definition.Trigger is IScheduledTrigger scheduled&&await store.GetAsync(definition.Id,ct).ConfigureAwait(false)is null)await store.SetAsync(new(definition.Id,scheduled.NextAfter(now)),ct).ConfigureAwait(false);}public async ValueTask<IReadOnlyList<AutomationRunResult>>TickAsync(DateTimeOffset now,CancellationToken ct=default){await gate.WaitAsync(ct).ConfigureAwait(false);try{List<AutomationRunResult>runs=[];foreach(AutomationDefinition automation in a.Values.Where(x=>x.Trigger is IScheduledTrigger).OrderBy(x=>x.Id,StringComparer.Ordinal)){AutomationScheduleState?state=await store.GetAsync(automation.Id,ct).ConfigureAwait(false);if(state?.NextDue is not DateTimeOffset due||due>now)continue;runs.Add(await ExecuteAsync(automation,ct).ConfigureAwait(false));IScheduledTrigger scheduled=(IScheduledTrigger)automation.Trigger;DateTimeOffset next=due;do{next=scheduled.NextAfter(next);}while(next<=now);await store.SetAsync(new(automation.Id,next),ct).ConfigureAwait(false);}return runs;}finally{gate.Release();}}public async ValueTask<IReadOnlyList<AutomationRunResult>>PublishSignalAsync(string resource,string?eventName=null,CancellationToken ct=default){ArgumentException.ThrowIfNullOrWhiteSpace(resource);List<AutomationRunResult>runs=[];foreach(AutomationDefinition automation in a.Values.OrderBy(x=>x.Id,StringComparer.Ordinal)){if(automation.Trigger is not WatchTriggerDefinition w||!w.Resource.Equals(resource,StringComparison.OrdinalIgnoreCase)||!(w.Event is null||w.Event.Equals(eventName,StringComparison.OrdinalIgnoreCase)))continue;runs.Add(await ExecuteAsync(automation,ct).ConfigureAwait(false));}return runs;}private async ValueTask<AutomationRunResult>ExecuteAsync(AutomationDefinition automation,CancellationToken ct){List<ExecutionStepResult>steps=[];try{object?result=await executor.ExecuteAsync(automation.Template.Compilation.Plan!,steps,new WorkflowRunState(),ct).ConfigureAwait(false);return new(automation,steps,result,null);}catch(Exception e){return new(automation,steps,null,e);}}}
